// Ear clipping: the triangles of a simple polygon, as triples of indices into its points.
const cross = (a, b, c) => (b[0] - a[0]) * (c[1] - a[1]) - (b[1] - a[1]) * (c[0] - a[0]);

export function triangulate(points) {
  const ring = points.map((_, i) => i);
  const triangles = [];
  while (ring.length > 3) {
    const [i, j, l] = ring;
    triangles.push([i, j, l]);
    ring.splice(1, 1);
  }
  if (ring.length === 3) triangles.push(ring);
  return triangles;
}

